using Microsoft.EntityFrameworkCore;using SPharmacyLog.Data.Entities;namespace SPharmacyLog.Data;public sealed class PharmacyDbContext(DbContextOptions<PharmacyDbContext> options):DbContext(options){public DbSet<PharmacyUser> Users=>Set<PharmacyUser>();public DbSet<Customer> Customers=>Set<Customer>();public DbSet<Prescription> Prescriptions=>Set<Prescription>();public DbSet<MedicineCatalogItem> Medicines=>Set<MedicineCatalogItem>();public DbSet<BorrowingRecord> Borrowings=>Set<BorrowingRecord>();public DbSet<Subscription> Subscriptions=>Set<Subscription>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<LedgerEntry> LedgerEntries=>Set<LedgerEntry>();protected override void OnModelCreating(ModelBuilder b){b.Entity<PharmacyUser>().HasIndex(x=>x.Username).IsUnique();b.Entity<Customer>().HasIndex(x=>x.CustomerNumber).IsUnique();b.Entity<Prescription>().HasIndex(x=>x.ExpiryDate);b.Entity<BorrowingRecord>().HasIndex(x=>x.InternalBarcode).IsUnique();b.Entity<Prescription>().HasOne(x=>x.Customer).WithMany(x=>x.Prescriptions).HasForeignKey(x=>x.CustomerId);b.Entity<BorrowingRecord>().HasOne(x=>x.Customer).WithMany(x=>x.Borrowings).HasForeignKey(x=>x.CustomerId);b.Entity<Subscription>().HasOne(x=>x.Customer).WithMany(x=>x.Subscriptions).HasForeignKey(x=>x.CustomerId);b.Entity<Payment>().HasOne(x=>x.Customer).WithMany(x=>x.Payments).HasForeignKey(x=>x.CustomerId);b.Entity<LedgerEntry>().HasOne(x=>x.Customer).WithMany(x=>x.LedgerEntries).HasForeignKey(x=>x.CustomerId);}}